.comparative-wrapper {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  justify-content: center;
  font-family: 'Segoe UI', sans-serif;
  margin-bottom: 30px;
}

.comparative-card {
  flex: 1 1 320px;
  max-width: 360px;
  border: 1px solid #e0e0e0;
  border-radius: 14px;
  overflow: hidden;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06);
  transition: transform 0.3s ease;
  background-color: #fff;
}

.comparative-card:hover {
  transform: translateY(-5px);
}

.comparative-card img {
  width: 100%;
  height: auto;
  display: block;
}

.comparative-card .card-body {
  padding: 20px;
}

.comparative-card h2 {
  font-size: 1.15em;
  color: #2b2b2b;
  margin-bottom: 10px;
}

/* BTU tags */
.btu-tag-group {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin: 10px 0 18px 0;
  flex-wrap: wrap;
}

.btu-tag {
  background: #f8f8f8;
  border: 1px solid #ccc;
  border-radius: 8px;
  padding: 6px 12px;
  font-size: 0.85em;
  color: #333;
  text-align: center;
  flex: 1 1 calc(33.333% - 8px);
  text-decoration: none;
  transition: all 0.25s ease;
  box-sizing: border-box;
}

.btu-tag small {
  display: block;
  color: #d32f2f;
  font-weight: bold;
  font-size: 0.9em;
}

.btu-tag:hover {
  background-color: #0066cc;
  color: #fff;
  border-color: #0066cc;
}

.btu-tag:hover small {
  color: #fff;
}

.btu-tag.active {
  background-color: #0066cc;
  color: #fff;
  border-color: #0066cc;
}

.btu-tag.active small {
  color: #fff;
}

.comparative-card .price {
  color: #d32f2f;
  font-weight: bold;
  font-size: 1.15em;
  margin-bottom: 12px;
}

.comparative-card .features {
  font-size: 0.95em;
  color: #444;
  margin-bottom: 12px;
  line-height: 1.6em;
}

.comparative-card .highlight {
  background: #f6fafd;
  padding: 8px 10px;
  border-left: 3px solid #0066cc;
  border-radius: 4px;
  font-size: 0.9em;
  color: #0066cc;
  margin-bottom: 12px;
}

.comparative-card .btn-group a {
  display: inline-block;
  margin: 5px 0;
  padding: 10px 18px;
  font-weight: bold;
  text-decoration: none;
  border-radius: 6px;
  font-size: 0.95em;
}

.comparative-card .btn-primary {
  background-color: #0066cc;
  color: #fff;
}

.comparative-card .btn-success {
  background-color: #43a047;
  color: #fff;
}
</style>

