<style>
.climaticpro-table {
  font-family: "Segoe UI", sans-serif;
  padding: 20px;
}
.climaticpro-table h2 {
  text-align: center;
  font-size: 24px;
  margin-bottom: 20px;
}
.table-wrapper {
  overflow-x: auto;
}
.climaticpro-table table {
  width: 100%;
  border-collapse: collapse;
  min-width: 768px;
}
.climaticpro-table th,
.climaticpro-table td {
  padding: 10px;
  text-align: center;
  border: 1px solid #ddd;
  vertical-align: middle;
}
.climaticpro-table th {
  background-color: #f3f4f6;
  font-weight: 600;
}
.climaticpro-table td img {
  max-width: 70px;
  height: auto;
  border-radius: 6px;
}
.climaticpro-table tr:nth-child(even) {
  background-color: #fafafa;
}
.premium-benefits {
  background-color: #e4f9ec;
  font-weight: 500;
}
.premium-benefits ul {
  margin: 5px 0 0 0;
  padding: 0;
  list-style: none;
  text-align: left;
}
.premium-benefits ul li {
  margin: 4px 0;
  font-size: 14px;
  cursor: help;
}
@media (max-width: 767px) {
  .climaticpro-table h2 {
    font-size: 20px;
  }
  .climaticpro-table td img {
    max-width: 50px;
  }
}
</style>
