  <h2>Alte materiale și costuri suplimentare</h2>
  <div class="table-wrapper">
    <table>
      <thead>
        <tr>
          <th>Serviciu / Material</th>
          <th>Descriere</th>
          <th>Cost</th>
        </tr>
