        </tr>
        <tr>
          <td>Montaj cu nacelă</td>
          <td>Se aplică per zi, indiferent de număr unități</td>
          <td>1099 Lei / zi</td>
        </tr>

        <tr class="category-row"><td colspan="3">Deplasări</td></tr>
        <tr>
          <td>Deplasare suplimentară</td>
          <td>Pentru finalizare instalare din cauze externe</td>
          <td>250 Lei / deplasare</td>
        </tr>
        <tr>
          <td>Montaj intern în casa scării</td>
          <td>Necesită scară specială sau acces dificil</td>
          <td>50 Lei / unitate</td>
        </tr>
      </tbody>
    </table>
